import json,hashlib
from pathlib import Path
R=Path(__file__).parent;D=R/'expanded-v8';D.mkdir();load=lambda p:json.loads(p.read_text());dump=lambda p,o:p.write_text(json.dumps(o,indent=2,ensure_ascii=False)+'\n')
for fn in ['questions.json','answer-key.json']:
 x=load(R/'expanded-v7'/fn);x['benchmark_version']='expanded-v8';dump(D/fn,x)
old=load(R/'expanded-v7/scope-map.json');allowed=['id','asked_question','required_answer_facts','contextual_key_background','source_references','scope_note'];entries=[{k:e[k] for k in allowed if k in e} for e in old['entries']]
m={'version':'scope-v8','principle':'Actual asked clauses only; scenario givens and source-backed contextual background are not extra response requirements. No reader/grade/performance history in this source-review packet.','entries':entries};dump(D/'scope-map.json',m);dump(D/'grading-key.json',{'version':'grading-key-v8','baseline':'answer-key.json','scope_map':'scope-map.json','answers':[{**e,'expected_answer':' '.join(e['required_answer_facts'])} for e in entries]})
(D/'question-bank.md').write_text('# Lords of Vegas — expanded-v8\n\n38 unchanged questions. Historical baseline answers remain intact. The effective source-only key separates actual asked facts from givens/background; versioned scope history is preserved in earlier banks and the run report.\n\n'+'\n\n'.join('## '+e['id']+'\n\n'+e['asked_question']+'\n\n'+' '.join(e['required_answer_facts'])+'\n\nSource: '+e['source_references'] for e in entries)+'\n')
l=load(R/'coverage-ledger-v7.json');l.pop('historical_correction',None)
for x in l['rejected_candidates']:
 if 'Restate sprawl boss rule as an extra Q31' in x['candidate']:x['reason']='Q31 gives failed control preventing sprawl and asks trade continuation and off-turn substitution; Q36 directly asks boss eligibility.'
l['stopping_rule']='38 questions; final targeted source/actual-clause passes18/19 each add zero. No performance or reader/grade history is part of this source-only review packet.';dump(R/'coverage-ledger-v8.json',l)
q=load(D/'questions.json');k=load(D/'answer-key.json');dump(D/'bank-freeze-manifest.json',{'benchmark':'expanded-v8','question_count':38,'files':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in D.iterdir() if p.is_file()},'unchanged_baseline_entries':{'all38questions':q['questions']==load(R/'expanded-v7/questions.json')['questions'],'all38baseline_answers':k['answers']==load(R/'expanded-v7/answer-key.json')['answers']},'required_facts_equal_v7':all(a['required_answer_facts']==b['required_answer_facts'] for a,b in zip(entries,old['entries']))})
dump(R/'source-review-packet-hygiene.json',{'reason':'Earlier active scope files inherited version-history comments, including a sentence that old seed answers contained an extra fact. These comments are not source authority and should not be supplied to a final independent reviewer.','historical_files_unchanged':True,'v8_changes':'Source-only current scope/key remove process/performance revision comments. Q01–38 wording, baseline answers and effective required facts unchanged fromv7. Current coverage ledger excludes process/performance commentary; source coverage facts and rejection logic retained.','final_review_requirement':'A NEW reviewer sees only authoritative sources and this sanitized v8 source/key/scope/ledger packet; no prior raw answers, grades, findings, metadata or process reports.','separate_source_audit':'Pure source auditor never saw any bank/key/history file. Its unchanged-text PASS remains applicable.'})
print('v8:38unchanged questions and targets; source-review history comments removed')
